67	  /**
68	   * Returns the data type stored in Pinot that is associated with the given Avro type.
69	   */
70	  public static DataType valueOf(Schema.Type avroType) {
71	    switch (avroType) {
72	      case INT:
73	        return DataType.INT;
74	      case LONG:
75	        return DataType.LONG;
76	      case FLOAT:
77	        return DataType.FLOAT;
