   *   <li>decimal (Avro bytes with logicalType {@code decimal}) &rarr; {@link java.math.BigDecimal}</li>
   * </ul>
   * Nested structures are handled so that logical types at any depth can be resolved:
   * <ul>
   *   <li>ARRAY: each element is converted if the element type has a logical type, and each element is recursively
   *   processed if the element type is a RECORD.</li>
   *   <li>MAP: each value is converted if the value type has a logical type, and each value is recursively processed
   *   if the value type is a RECORD.</li>
   * </ul>
   * Fields without a logical type that are not part of an ARRAY or MAP are passed through unchanged. Union schemas are
   * handled by selecting the sub-schema that carries a logical type when one is present.
   *
   * @param record the Avro record to convert
   * @return a new {@link GenericRecord} with all logical type fields converted, or {@code null} if the input is
   *     {@code null}
   */
  public static GenericRecord convertLogicalType(GenericRecord record) {
    if (record == null) {
      return null;
    }
    Schema schema = record.getSchema();
    GenericRecord result = new GenericData.Record(schema);
    for (Schema.Field field : schema.getFields()) {
      Object value = record.get(field.pos());
      result.put(field.pos(), convertFieldValue(value, field.schema()));
    }
    return result;
  }

  /**
   * Converts the value of a top-level record field according to its schema. Logical type fields are converted, while
   * ARRAY and MAP fields have their elements/values processed recursively. Any other field is returned unchanged.
   */
  private static Object convertFieldValue(Object value, Schema schema) {
    if (value == null) {
      return null;
    }
    Schema resolvedSchema = resolveSchema(schema);
    LogicalType logicalType = LogicalTypes.fromSchemaIgnoreInvalid(resolvedSchema);
    if (logicalType != null) {
      return applyLogicalTypeConversion(value, resolvedSchema, logicalType);
    }
    switch (resolvedSchema.getType()) {
      case ARRAY:
        return convertArray(value, resolvedSchema.getElementType());
      case MAP:
        return convertMap(value, resolvedSchema.getValueType());
      default:
        return value;
    }
  }

  /**
   * Converts each element of an array. An element is converted when its type has a logical type and is recursively
   * processed when its type is a RECORD; otherwise it is passed through unchanged.
   */
  private static Object convertArray(Object value, Schema elementSchema) {
    if (!(value instanceof List)) {
      return value;
    }
    List<?> list = (List<?>) value;
    List<Object> converted = new ArrayList<>(list.size());
    for (Object element : list) {
      converted.add(convertNestedElement(element, elementSchema));
    }
    return converted;
  }

  /**
   * Converts each value of a map. A value is converted when its type has a logical type and is recursively processed
   * when its type is a RECORD; otherwise it is passed through unchanged.
   */
  private static Object convertMap(Object value, Schema valueSchema) {
    if (!(value instanceof Map)) {
      return value;
    }
    Map<?, ?> map = (Map<?, ?>) value;
    Map<Object, Object> converted = new HashMap<>();
    for (Map.Entry<?, ?> entry : map.entrySet()) {
      converted.put(entry.getKey(), convertNestedElement(entry.getValue(), valueSchema));
    }
    return converted;
  }

  /**
   * Converts a single nested element (array element or map value). Applies the logical type conversion when the element
   * schema carries a logical type, recurses when it is a RECORD, and otherwise returns the element unchanged.
   */
  private static Object convertNestedElement(Object element, Schema elementSchema) {
    if (element == null) {
      return null;
    }
    Schema resolvedSchema = resolveSchema(elementSchema);
    LogicalType logicalType = LogicalTypes.fromSchemaIgnoreInvalid(resolvedSchema);
    if (logicalType != null) {
      return applyLogicalTypeConversion(element, resolvedSchema, logicalType);
    }
    if (resolvedSchema.getType() == Schema.Type.RECORD && element instanceof GenericRecord) {
      return convertLogicalType((GenericRecord) element);
    }
    return element;
  }

  /**
   * Applies the Avro conversion associated with the given logical type. If no conversion is known for the logical type,
   * the value is returned unchanged.
   */
  private static Object applyLogicalTypeConversion(Object value, Schema schema, LogicalType logicalType) {
    Conversion<?> conversion = findConversionFor(logicalType.getName());
    if (conversion == null) {
      return value;
    }
    return Conversions.convertToLogicalType(value, schema, logicalType, conversion);
  }

  /**
   * Resolves the effective schema for a field. For union schemas, the sub-schema carrying a logical type is preferred;
   * otherwise the first non-null sub-schema is returned. Non-union schemas are returned unchanged.
   */
  private static Schema resolveSchema(Schema schema) {
    if (!schema.isUnion()) {
      return schema;
    }
    Schema firstNonNull = null;
    for (Schema curSchema : schema.getTypes()) {
      if (curSchema.getLogicalType() != null) {
        return curSchema;
      }
      if (firstNonNull == null && curSchema.getType() != Schema.Type.NULL) {
        firstNonNull = curSchema;
      }
    }
    return firstNonNull != null ? firstNonNull : schema;
  }
